import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template
// literal — see Week 8 Day 1.1, concept 2.

await writeProjectFile("week8/generated/day2-negative.spec.ts", `// Week 8, Day 2 — negative scenarios: what this API really does when you
// give it bad input.
//
// Every expectation below was probed against the live API first. Several
// contradict what you would assume from the documentation, which is the point:
// a negative test asserts observed behaviour, not hoped-for behaviour.
//
// Written by a cell in week8/day2_2.ipynb. Run it yourself:
//   npx playwright test week8/generated/day2-negative.spec.ts
import { test, expect } from "@playwright/test";

const BASE = "https://restful-booker.herokuapp.com";

const validBooking = {
  firstname: "Jim",
  lastname: "Brown",
  totalprice: 111,
  depositpaid: true,
  bookingdates: { checkin: "2018-01-01", checkout: "2019-01-01" },
  additionalneeds: "Breakfast",
};

test.describe("Negative scenarios", () => {
  test("wrong credentials return 200, with a reason instead of a token", async ({ request }) => {
    const res = await request.post(\`\${BASE}/auth\`, {
      data: { username: "admin", password: "definitely-wrong" },
    });

    // Not 401. A failed login is still a successful *request*, and this API
    // reports the failure in the body rather than the status code.
    expect(res.status()).toBe(200);

    const body = await res.json();
    expect(body.token).toBeUndefined();
    expect(body.reason).toBe("Bad credentials");
  });

  test("a blank first name is accepted", async ({ request }) => {
    const res = await request.post(\`\${BASE}/booking\`, {
      data: { ...validBooking, firstname: "" },
    });

    expect(res.status()).toBe(200);
    const body = await res.json();
    // No validation at all — the empty string is stored as-is.
    expect(body.booking.firstname).toBe("");
  });

  test("a wrong type is silently turned into null", async ({ request }) => {
    const res = await request.post(\`\${BASE}/booking\`, {
      data: { ...validBooking, totalprice: "not-a-number" },
    });

    expect(res.status()).toBe(200);
    const body = await res.json();
    // Worse than a rejection: the request "succeeds" and the data is quietly
    // destroyed. Exactly the kind of bug only a negative test finds.
    expect(body.booking.totalprice).toBeNull();
  });

  test("a missing required field crashes the server", async ({ request }) => {
    const { firstname, ...withoutFirstname } = validBooking;
    const res = await request.post(\`\${BASE}/booking\`, { data: withoutFirstname });

    // 500 means the server threw. A well-built API would answer 400 and explain
    // which field was missing. Report this as a defect — do not "fix" the test.
    expect(res.status()).toBe(500);
  });

  test("an unknown booking id gives 404", async ({ request }) => {
    const res = await request.get(\`\${BASE}/booking/99999999\`);
    expect(res.status()).toBe(404);
  });

  test("changing a booking without a token gives 403", async ({ request }) => {
    const created = await request.post(\`\${BASE}/booking\`, { data: validBooking });
    const { bookingid } = await created.json();

    const res = await request.put(\`\${BASE}/booking/\${bookingid}\`, { data: validBooking });
    expect(res.status()).toBe(403);
  });

  test("a delete response is not JSON, so parsing it throws", async ({ request }) => {
    const auth = await request.post(\`\${BASE}/auth\`, {
      data: { username: "admin", password: "password123" },
    });
    const { token } = await auth.json();

    const created = await request.post(\`\${BASE}/booking\`, { data: validBooking });
    const { bookingid } = await created.json();

    const del = await request.delete(\`\${BASE}/booking/\${bookingid}\`, {
      headers: { Cookie: \`token=\${token}\` },
    });

    expect(del.status()).toBe(201);

    // The body is the seven characters "Created" — plain text, not JSON.
    const text = await del.text();
    expect(text).toBe("Created");

    // This is why calling .json() on a delete blows up with a confusing error.
    await expect(del.json()).rejects.toThrow();
  });
});
`);

await runSpec("week8/generated/day2-negative.spec.ts");

