await writeProjectFile("week8/generated/day2-data-driven.spec.ts", `// Week 8, Day 2 — one test, many data sets.
//
// The four cases live in day2-booking-data.json. Adding a fifth means editing
// that file and nothing else: no new test, no copy-pasted block.
//
// Written by a cell in week8/day2_2.ipynb. Run it yourself:
//   npx playwright test week8/generated/day2-data-driven.spec.ts
import { test, expect } from "@playwright/test";
import testData from "./day2-booking-data.json";

const BASE = "https://restful-booker.herokuapp.com";

test.describe("Create a booking, once per data set", () => {
  // The loop runs while Playwright is *collecting* tests, so each case becomes
  // its own test with its own name, its own pass/fail, and its own retry.
  // That is the whole reason to loop out here rather than inside one test.
  testData.cases.forEach((testCase, index) => {
    test(\`Case \${index + 1} — \${testCase.name}\`, async ({ request }) => {
      const res = await request.post(\`\${BASE}/booking\`, {
        headers: { "Content-Type": "application/json" },
        data: testCase.booking,
      });

      expect(res.status()).toBe(testCase.expectedStatus);

      const body = await res.json();

      // Assert against the data file, never against a value typed twice.
      expect(body.booking.firstname).toBe(testCase.expectedFirstname);
      expect(body.booking.lastname).toBe(testCase.booking.lastname);
      expect(body.booking.bookingdates.checkin).toBe(testCase.booking.bookingdates.checkin);
      expect(body.bookingid).toBeTruthy();
    });
  });
});
`);

await runSpec("week8/generated/day2-data-driven.spec.ts");

// A type: the shape, written down once.
type Booking = {
  firstname: string;
  lastname: string;
  totalprice: number;
  depositpaid: boolean;
  bookingdates: { checkin: string; checkout: string };
  additionalneeds?: string;
};

// A factory: sensible defaults, overridable per case.
// Returning a fresh object each call is the point — no two cases share state.
function aBooking(overrides: Partial<Booking> = {}): Booking {
  return {
    firstname: "Ada",
    lastname: "Lovelace",
    totalprice: 350,
    depositpaid: true,
    bookingdates: { checkin: "2024-05-01", checkout: "2024-05-08" },
    additionalneeds: "Late checkout",
    ...overrides,
  };
}

console.log(JSON.stringify(aBooking()));
console.log(JSON.stringify(aBooking({ firstname: "", totalprice: 0 })));

// A typo is now caught before the test ever runs:
// aBooking({ frstname: "x" });   // ← uncomment: TypeScript refuses

// `Booking` and `aBooking` come from the cell above — cells share one workspace,
// so there is no need to define them twice (and doing so would be an error).
type Case = { name: string; booking: Booking; expectedStatus: number };

const cases: Case[] = [
  { name: "a normal booking",     booking: aBooking(),                      expectedStatus: 200 },
  { name: "a free stay",          booking: aBooking({ totalprice: 0 }),     expectedStatus: 200 },
  { name: "no deposit",           booking: aBooking({ depositpaid: false }), expectedStatus: 200 },
  { name: "NEGATIVE blank name",  booking: aBooking({ firstname: "" }),     expectedStatus: 200 },
];

cases.forEach((c, i) => console.log(`Case ${i + 1} — ${c.name} → ${c.expectedStatus}`));
